begin
  select id into v_uid from public.profiles
   where es_prueba and lower(email) = 'prospect@flyergalicia.test';
  if v_uid is null then raise exception 'No encontré la cuenta de prueba Prospect'; end if;

  delete from public.padron_empresas pe
   where pe.user_id = v_uid
     and lower(trim(pe.empresa)) in (select lower(trim(r->>'empresa')) from jsonb_array_elements(v_rows) r);

  insert into public.padron_empresas (user_id, empresa, cuits, config, asesores, rubro)
  select v_uid, r->>'empresa',
         coalesce((select array_agg(c) from jsonb_array_elements_text(r->'cuits') c), '{}'),
         coalesce(r->>'config', ''), r->'asesores', coalesce(r->'rubro', '{}'::jsonb)
    from jsonb_array_elements(v_rows) r;
end $$;

select count(*) as empresas_de_prospect
  from public.padron_empresas pe join public.profiles p on p.id = pe.user_id
 where p.es_prueba and lower(p.email) = 'prospect@flyergalicia.test';
